    rid = "00000000-0000-4000-8000-000000000000"

    class Store:
        def verify_deletion_tombstones(self, *a, **k):
            return json.dumps(
                {
                    "request_id": rid,
                    "verified": False,
                    "coverage": "complete",
                    "tombstone_count": 1,
                    "evidence_digest": "a" * 64,
                    "reasons": [
                        "tombstone_record_invalid",
                        "evidence_digest_mismatch",
                        "evidence_digest_mismatch",
                    ],
                },
                separators=(",", ":"),
            ) + "\n"

    fixture = self._serve(Store())
    try:
        status, data = self._get(
            fixture.port, f"/requests/{rid}/tombstone-verification"
        )
        # A duplicate/unsorted reason list is not the store's
        # canonical contract and is rejected as a malformed report.
        self.assertEqual(status, 503)
        self.assertEqual(data, STORAGE_UNAVAILABLE)
    finally:
        fixture.__exit__(None, None, None)

